window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-14f0c4a6b79e8553"]={"versions": [{"id": "FIG-14f0c4a6b79e8553", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>):</li>\n<li>Oberstes Hüll-Element der Systembeschreibung.</li>\n<li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>).</li>\n<li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.</li>\n<li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):</li>\n<li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).</li>\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n<li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>CompositionSwComponentType</code></strong>:</li>\n<li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.</li>\n<li>Aggregiert per Komposition:</li>\n<li><code>+component</code> [0..\\*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.</li>\n<li><code>+connector</code> [0..\\*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.</li>\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n<li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.</li>\n<li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):</li>\n<li>Abstrakter Basistyp aller Software-Komponenten.</li>\n<li>Aggregiert <code>+port</code> [0..\\*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.</li>\n<li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):</li>\n<li>Abstrakter Interaktionspunkt einer SW-C.</li>\n<li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).</li>\n<li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) & <strong><code>AssemblySwConnector</code></strong>:</li>\n<li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.</li>\n<li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:</li>\n<li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.</li>\n<li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Methodik &amp; Binding)</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design & ECU Extraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).</li>\n<li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Hierarchisches Flattening:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.</li>\n<li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Variationspunkt-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) $\\rightarrow$ Komponenten- und Konnektor-Topologie (<code>postBuild</code>) $\\rightarrow$ Port-Schnittstellen (<code>preCompileTime</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Generierung:</strong></li>\n<li>Der <code>RootSwCompositionPrototype</code> ist die verbindliche Wurzel für den RTE-Generator. Nur Komponenten und Ports, die transitiv über diesen Pfad erreichbar sind, werden in den RTE-Contract- und Generation-Phasen berücksichtigt.</li>\n<li>Unverbundene R-Ports oder offene P-Ports führen je nach Konfiguration zu Warnungen oder Fehlern während der RTE-Validierung.</li>\n<li><strong>Instanzreferenzierung (<code>«instanceRef»</code>):</strong></li>\n<li>Entwickler von Generierungs- und Import-Tools müssen sicherstellen, dass <code>AssemblySwConnector</code> vollständige Komponenten-Instanzpfade (<code>contextComponent</code>) deklariert. Ein Verweis rein auf den <code>PortPrototype</code> ohne Kontext ist im Metamodell ungültig, da derselbe <code>SwComponentType</code> mehrfach instanziiert werden kann.</li>\n<li><strong>Variationspunkte & Post-Build-Fähigkeit:</strong></li>\n<li>Da <code>+component</code> und <code>+connector</code> als <code>vh.latestBindingTime = postBuild</code> annotiert sind, können Komponenteninstanzen und Assembly-Verbindungen theoretisch bis in die Post-Build-Phase variiert werden (z. B. Aktivierung/Deaktivierung bestimmter Features). Die Port-Definition (<code>preCompileTime</code>) erfordert jedoch zwingend ein fixes Interface-Layout vor der Kompilierung des Codes.</li>\n<li><strong>BSW- und Service-Integration:</strong></li>\n<li><code>ServiceSwComponentType</code> ist als Subklasse von <code>AtomicSwComponentType</code> abgebildet. BSW-Module (wie Dem, NvM, ComM), die Service-Ports bereitstellen, werden über dieselben Mechanismen (<code>SwComponentPrototype</code>, <code>AssemblySwConnector</code>) an Applikations-SW-Cs angebunden.</li>\n</ul>"}, {"id": "FIG-b32a5ffcd8a1ce29", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):</li>\n<li>Oberstes Hüll-Element der Systembeschreibung.</li>\n<li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>).</li>\n<li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.</li>\n<li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):</li>\n<li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).</li>\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n<li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [0..1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>CompositionSwComponentType</code></strong>:</li>\n<li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.</li>\n<li>Aggregiert per Komposition:</li>\n<li><code>+component</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.</li>\n<li><code>+connector</code> [0..*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.</li>\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n<li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.</li>\n<li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):</li>\n<li>Abstrakter Basistyp aller Software-Komponenten.</li>\n<li>Aggregiert <code>+port</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.</li>\n<li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):</li>\n<li>Abstrakter Interaktionspunkt einer SW-C.</li>\n<li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).</li>\n<li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) & <strong><code>AssemblySwConnector</code></strong>:</li>\n<li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.</li>\n<li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:</li>\n<li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.</li>\n<li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design & ECU Extraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).</li>\n<li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Hierarchisches Flattening:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.</li>\n<li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Variationspunkt-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) $\\rightarrow$ Komponenten- und Konnektor-Topologie (<code>postBuild</code>) $\\rightarrow$ Port-Schnittstellen (<code>preCompileTime</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kardinalitäts- und Typ-Integrität:</strong></li>\n<li>Die typisierende Zuordnung <code>+softwareComposition</code> von <code>RootSwCompositionPrototype</code> auf <code>CompositionSwComponentType</code> ist optional (<code>0..1</code>).</li>\n<li>Ein <code>System</code> kann optional (<code>0..1</code>) genau eine Root-Komposition (<code>+rootSoftwareComposition</code>) besitzen.</li>\n<li><code>AssemblySwConnector</code> referenziert über <code>«instanceRef»</code> jeweils maximal einen Provider- und einen Requester-Port (<code>0..1</code>).</li>\n<li><strong>Variabilitäts- und Splitbarkeitsregeln:</strong></li>\n<li>Die Aggregationen <code>+rootSoftwareComposition</code>, <code>+component</code>, <code>+connector</code> und <code>+port</code> sind als <code>«atpVariation, atpSplitable»</code> modelliert; damit sind sie über XML-Dateigrenzen hinweg aufteilbar und unterstützen AUTOSAR-Variantenbildung.</li>\n<li>Die jeweils annotierten Bindungszeiten (<code>systemDesignTime</code>, <code>postBuild</code>, <code>preCompileTime</code>) schränken den spätestmöglichen Zeitpunkt der Variantenauflösung verbindlich ein.</li>\n</ul>"}, {"id": "FIG-6323dc5ba8baa5e2", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):</li>\n<li>Oberstes Hüll-Element der Systembeschreibung.</li>\n<li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>).</li>\n<li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.</li>\n<li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):</li>\n<li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).</li>\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n<li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [0..1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>CompositionSwComponentType</code></strong>:</li>\n<li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.</li>\n<li>Aggregiert per Komposition:</li>\n<li><code>+component</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.</li>\n<li><code>+connector</code> [0..*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.</li>\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n<li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.</li>\n<li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):</li>\n<li>Abstrakter Basistyp aller Software-Komponenten.</li>\n<li>Aggregiert <code>+port</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.</li>\n<li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):</li>\n<li>Abstrakter Interaktionspunkt einer SW-C.</li>\n<li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).</li>\n<li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) & <strong><code>AssemblySwConnector</code></strong>:</li>\n<li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.</li>\n<li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:</li>\n<li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.</li>\n<li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design & ECU Extraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).</li>\n<li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Hierarchisches Flattening:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.</li>\n<li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Variationspunkt-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) $\\rightarrow$ Komponenten- und Konnektor-Topologie (<code>postBuild</code>) $\\rightarrow$ Port-Schnittstellen (<code>preCompileTime</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kardinalitäts- und Typ-Integrität:</strong></li>\n<li>Die typisierende Zuordnung <code>+softwareComposition</code> von <code>RootSwCompositionPrototype</code> auf <code>CompositionSwComponentType</code> ist optional (<code>0..1</code>).</li>\n<li>Ein <code>System</code> kann optional (<code>0..1</code>) genau eine Root-Komposition (<code>+rootSoftwareComposition</code>) besitzen.</li>\n<li><code>AssemblySwConnector</code> referenziert über <code>«instanceRef»</code> jeweils maximal einen Provider- und einen Requester-Port (<code>0..1</code>).</li>\n<li><strong>Variabilitäts- und Splitbarkeitsregeln:</strong></li>\n<li>Die Aggregationen <code>+rootSoftwareComposition</code>, <code>+component</code>, <code>+connector</code> und <code>+port</code> sind als <code>«atpVariation, atpSplitable»</code> modelliert; damit sind sie über XML-Dateigrenzen hinweg aufteilbar und unterstützen AUTOSAR-Variantenbildung.</li>\n<li>Die jeweils annotierten Bindungszeiten (<code>systemDesignTime</code>, <code>postBuild</code>, <code>preCompileTime</code>) schränken den spätestmöglichen Zeitpunkt der Variantenauflösung verbindlich ein.</li>\n</ul>"}, {"id": "FIG-1581a17468f50425", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):</li>\n<li>Oberstes Hüll-Element der Systembeschreibung.</li>\n<li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>, <code>mmt.RestrictToStandards = CP</code>).</li>\n<li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.</li>\n<li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):</li>\n<li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).</li>\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n<li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [0..1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>CompositionSwComponentType</code></strong>:</li>\n<li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.</li>\n<li>Aggregiert per Komposition:</li>\n<li><code>+component</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.</li>\n<li><code>+connector</code> [0..*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.</li>\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n<li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.</li>\n<li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.</li>\n<li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):</li>\n<li>Abstrakter Basistyp aller Software-Komponenten.</li>\n<li>Aggregiert <code>+port</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.</li>\n<li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):</li>\n<li>Abstrakter Interaktionspunkt einer SW-C.</li>\n<li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).</li>\n<li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) & <strong><code>AssemblySwConnector</code></strong>:</li>\n<li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.</li>\n<li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:</li>\n<li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.</li>\n<li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design & ECU Extraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).</li>\n<li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Hierarchisches Flattening:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.</li>\n<li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Variationspunkt-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) $\\rightarrow$ Komponenten- und Konnektor-Topologie (<code>postBuild</code>) $\\rightarrow$ Port-Schnittstellen (<code>preCompileTime</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kardinalitäts- und Typ-Integrität:</strong></li>\n<li>Die typisierende Zuordnung <code>+softwareComposition</code> von <code>RootSwCompositionPrototype</code> auf <code>CompositionSwComponentType</code> ist optional (<code>0..1</code>).</li>\n<li>Ein <code>System</code> kann optional (<code>0..1</code>) genau eine Root-Komposition (<code>+rootSoftwareComposition</code>) besitzen.</li>\n<li><code>AssemblySwConnector</code> referenziert über <code>«instanceRef»</code> jeweils maximal einen Provider- und einen Requester-Port (<code>0..1</code>).</li>\n<li><strong>Variabilitäts- und Standard-Einschränkungen:</strong></li>\n<li>Die Aggregationen <code>+rootSoftwareComposition</code>, <code>+component</code>, <code>+connector</code> und <code>+port</code> sind als <code>«atpVariation, atpSplitable»</code> modelliert; damit sind sie über XML-Dateigrenzen hinweg aufteilbar und unterstützen AUTOSAR-Variantenbildung.</li>\n<li>Die jeweils annotierten Bindungszeiten (<code>systemDesignTime</code>, <code>postBuild</code>, <code>preCompileTime</code>) schränken den spätestmöglichen Zeitpunkt der Variantenauflösung verbindlich ein.</li>\n<li>Die Komposition <code>+rootSoftwareComposition</code> ist durch das Tag <code>mmt.RestrictToStandards = CP</code> explizit auf die Classic Platform eingeschränkt.</li>\n</ul>"}], "trans": [{"from": "FIG-14f0c4a6b79e8553", "to": "FIG-b32a5ffcd8a1ce29", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>System</code></strong>: Stereotyp <code>«UploadableDesignElement»</code> hinzugefügt (neben <code>«ARElement»</code> und <code>«AtpStructureElement»</code>).</li>\n<li><strong><code>RootSwCompositionPrototype</code></strong>: Kardinalität der typisierenden Assoziation <code>+softwareComposition</code> zu <code>CompositionSwComponentType</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}, {"from": "FIG-b32a5ffcd8a1ce29", "to": "FIG-6323dc5ba8baa5e2", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6323dc5ba8baa5e2", "to": "FIG-1581a17468f50425", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Aggregation <code>+rootSoftwareComposition</code></strong>: Im Notizfeld für <code>«atpVariation» Tags</code> wurde der Tag <code>mmt.RestrictToStandards = CP</code> ergänzt.</li>\n</ul>"}]};
